import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 마감취소·승인취소 이력의 변경 구분은 스키마 허용값 안에서 마감취소='마감', 승인취소='승인'으로 남긴다.
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function mainBudgetIdOf(req: Request): string {
  const id = req.params['mainBudgetId'];
  if (typeof id !== 'string' || !/^[0-9]+$/.test(id)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '본예산 ID 형식이 올바르지 않습니다.');
  }
  return id;
}

function optionalText(v: unknown): string | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  return String(v);
}

function optionalInteger(v: unknown, label: string): string | null {
  const text = optionalText(v);
  if (text === null) {
    return null;
  }
  if (!/^-?[0-9]+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 형식이 올바르지 않습니다.');
  }
  return text;
}

async function changeStatus(
  db: any,
  id: string,
  userId: string,
  from: string,
  to: string,
  changeType: string,
  conflictMessage: string,
) {
  const rows = await db.query(
    'SELECT status AS "status" FROM main_budget WHERE main_budget_id = CAST(:id AS bigint) FOR UPDATE',
    { id },
  );
  if (rows.length === 0) {
    throw new ApiError(404, 'MAIN_BUDGET_NOT_FOUND', '대상 본예산을 찾을 수 없습니다.');
  }
  if (rows[0].status !== from) {
    throw new ApiError(409, 'MAIN_BUDGET_STATUS_CONFLICT', conflictMessage + ' (현재 상태: ' + rows[0].status + ')');
  }
  await db.execute(
    'UPDATE main_budget SET status = :to, updated_at = now() WHERE main_budget_id = CAST(:id AS bigint)',
    { id, to },
  );
  await db.execute(
    'INSERT INTO change_history (target_type, target_id, change_type, changed_at, changer_id, before_content, after_content, created_at, updated_at) ' +
      'VALUES (:targetType, CAST(:id AS bigint), :changeType, now(), CAST(:userId AS bigint), :before, :after, now(), now())',
    {
      targetType: 'main_budget',
      id,
      changeType,
      userId,
      before: '상태: ' + from,
      after: '상태: ' + to,
    },
  );
  return { status: to };
}

@Controller('api/v1')
export class FnSfr00302Controller {
  @Get('/main-budgets')
  async listMainBudgets(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '시스템 관리자');
    const q: any = checks.queryOf(req.query);
    const fiscalYear = optionalInteger(q['fiscalYear'], '기수');
    const projectId = optionalInteger(q['projectId'], '프로젝트 ID');
    const pageText = optionalInteger(q['page'], 'page');
    const sizeText = optionalInteger(q['size'], 'size');
    const status = optionalText(q['status']);
    if (status !== null && !['신청', '마감', '마감취소', '승인', '승인취소'].includes(status)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '상태 값이 올바르지 않습니다.');
    }
    const page = pageText === null ? 0 : Math.max(0, Number(pageText));
    const size = sizeText === null ? DEFAULT_SIZE : Math.min(MAX_SIZE, Math.max(1, Number(sizeText)));
    const params = {
      accountingUnit: optionalText(q['accountingUnit']),
      fiscalYear,
      projectId,
      budgetGroup: optionalText(q['budgetGroup']),
      status,
    };
    const where =
      ' FROM main_budget mb JOIN budget_item bi ON bi.budget_item_id = mb.budget_item_id' +
      ' WHERE (CAST(:accountingUnit AS varchar) IS NULL OR mb.accounting_unit = CAST(:accountingUnit AS varchar))' +
      ' AND (CAST(:fiscalYear AS integer) IS NULL OR mb.fiscal_year = CAST(:fiscalYear AS integer))' +
      ' AND (CAST(:projectId AS bigint) IS NULL OR mb.project_id = CAST(:projectId AS bigint))' +
      ' AND (CAST(:budgetGroup AS varchar) IS NULL OR bi.budget_group = CAST(:budgetGroup AS varchar))' +
      ' AND (CAST(:status AS varchar) IS NULL OR mb.status = CAST(:status AS varchar))';
    return transaction(async (db) => {
      const items = await db.query(
        'SELECT mb.main_budget_id AS "mainBudgetId", mb.project_id AS "projectId", mb.budget_item_id AS "budgetItemId",' +
          ' mb.accounting_unit AS "accountingUnit", mb.fiscal_year AS "fiscalYear", mb.request_amount AS "requestAmount",' +
          ' mb.status AS "status"' +
          where +
          ' ORDER BY mb.main_budget_id DESC LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { ...params, size, offset: page * size },
      );
      const counts = await db.query('SELECT COUNT(*) AS "total"' + where, params);
      return { items, page, size, total: Number(counts[0].total) };
    });
  }

  @Post('/main-budgets/:mainBudgetId/close')
  @HttpCode(200)
  async closeMainBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '시스템 관리자');
    const id = mainBudgetIdOf(req);
    return transaction(async (db) => {
      return changeStatus(db, id, user.id, '신청', '마감', '마감', '신청 상태의 본예산만 마감할 수 있습니다.');
    });
  }

  @Post('/main-budgets/:mainBudgetId/cancel-close')
  @HttpCode(200)
  async cancelCloseMainBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '시스템 관리자');
    const id = mainBudgetIdOf(req);
    return transaction(async (db) => {
      return changeStatus(db, id, user.id, '마감', '마감취소', '마감', '마감 상태의 본예산만 마감취소할 수 있습니다.');
    });
  }

  @Post('/main-budgets/:mainBudgetId/submit-approval')
  @HttpCode(200)
  async submitMainBudgetApproval(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '시스템 관리자');
    const id = mainBudgetIdOf(req);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status AS "status", approval_document_id AS "approvalDocumentId" FROM main_budget WHERE main_budget_id = CAST(:id AS bigint) FOR UPDATE',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'MAIN_BUDGET_NOT_FOUND', '대상 본예산을 찾을 수 없습니다.');
      }
      if (rows[0].status !== '마감') {
        throw new ApiError(409, 'MAIN_BUDGET_NOT_CLOSED', '마감된 본예산만 전자결재로 상신할 수 있습니다. 먼저 마감하세요.');
      }
      if (rows[0].approvalDocumentId !== null && rows[0].approvalDocumentId !== undefined) {
        // 가정: 이미 결재문서가 연결된 본예산은 기존 결재문서를 그대로 돌려준다.
        return { approvalDocumentId: Number(rows[0].approvalDocumentId), submitResult: '이미 상신된 결재문서입니다.' };
      }
      // 가정: 전자결재 모듈 상신 응답을 받을 수 없어 상신 실패로 처리하고 상태는 바꾸지 않는다.
      // TODO(질문): 전자결재 모듈 호출 방식과 approval_document 필수 값(결재양식·기안부서) 출처가 없다.
      throw new ApiError(502, 'APPROVAL_SUBMIT_FAILED', '전자결재 연계에 실패했습니다. 잠시 후 다시 시도하세요.');
    });
  }

  @Post('/main-budgets/:mainBudgetId/approve')
  @HttpCode(200)
  async approveMainBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '시스템 관리자');
    const id = mainBudgetIdOf(req);
    return transaction(async (db) => {
      return changeStatus(db, id, user.id, '마감', '승인', '승인', '마감 상태의 본예산만 승인할 수 있습니다.');
    });
  }

  @Post('/main-budgets/:mainBudgetId/cancel-approval')
  @HttpCode(200)
  async cancelApprovalMainBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '시스템 관리자');
    const id = mainBudgetIdOf(req);
    return transaction(async (db) => {
      return changeStatus(db, id, user.id, '승인', '승인취소', '승인', '승인 상태의 본예산만 승인취소할 수 있습니다.');
    });
  }
}

