import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  TextInput,
  NumberInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const STATUS_OPTIONS: [string, string][] = [
  ['신청', '신청'],
  ['마감', '마감'],
  ['마감취소', '마감취소'],
  ['승인', '승인'],
  ['승인취소', '승인취소'],
];

// 현재 상태에서 가능한 처리: [동작 경로, 버튼 이름, 완료 문장]
const ACTIONS: Record<string, [string, string, string][]> = {
  '신청': [['close', '마감', '마감했습니다.']],
  '마감': [
    ['submit-approval', '전자결재 상신', '전자결재로 상신했습니다.'],
    ['approve', '승인', '승인했습니다.'],
    ['cancel-close', '마감취소', '마감을 취소했습니다.'],
  ],
  '승인': [['cancel-approval', '승인취소', '승인을 취소했습니다.']],
};

export default function FnSfr00302Page({ role, notify }: PageProps) {
  const [draft, setDraft] = useState<Row>({});
  const [query, setQuery] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [target, setTarget] = useState<Row | null>(null);
  const [action, setAction] = useState<[string, string, string] | null>(null);

  const list = useData<Page>(
    () => call<Page>('GET', '/main-budgets', role, undefined, { ...query, page, size: 20 }),
    [role, query, page],
  );
  const waiting = useData<Page>(
    () => call<Page>('GET', '/main-budgets', role, undefined, { status: '마감', page: 0, size: 5 }),
    [role],
  );

  const rows = list.data ? list.data.items : [];
  const total = list.data ? list.data.total : 0;
  const pageAmount = rows.reduce((sum, r) => sum + Number(r.requestAmount || 0), 0);
  const closedCount = waiting.data ? waiting.data.total : 0;

  function setDraftValue(key: string, value: unknown) {
    setDraft({ ...draft, [key]: value });
  }

  function search() {
    setPage(0);
    setQuery({ ...draft });
  }

  function reset() {
    setDraft({});
    setPage(0);
    setQuery({});
  }

  function openAction(row: Row, act: [string, string, string]) {
    setTarget(row);
    setAction(act);
  }

  function closeDrawer() {
    setTarget(null);
    setAction(null);
  }

  async function run() {
    if (!target || !action) {
      return;
    }
    await call('POST', '/main-budgets/' + target.mainBudgetId + '/' + action[0], role, {});
    notify(action[2]);
    closeDrawer();
    list.reload();
    waiting.reload();
  }

  const columns: Column[] = [
    { key: 'mainBudgetId', label: '본예산 ID' },
    { key: 'accountingUnit', label: '회계단위' },
    { key: 'fiscalYear', label: '기수(회계연도)' },
    { key: 'projectId', label: '프로젝트', render: (r) => <RefName table='project' role={role} value={r.projectId} /> },
    { key: 'budgetItemId', label: '예산과목', render: (r) => <RefName table='budget_item' role={role} value={r.budgetItemId} /> },
    { key: 'requestAmount', label: '신청금액', render: (r) => <Num value={r.requestAmount} /> },
    { key: 'status', label: '상태', render: (r) => <Badge value={r.status} /> },
    {
      key: 'actions',
      label: '처리',
      render: (r) => (
        <span>
          {(ACTIONS[String(r.status)] || []).map((act) => (
            <button key={act[0]} type='button' onClick={(e) => { e.stopPropagation(); openAction(r, act); }}>
              {act[1]}
            </button>
          ))}
        </span>
      ),
    },
  ];

  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>본예산 현황</h2>
        <Tiles
          items={[
            ['조회 건수', <Num value={total} />],
            ['현재 쪽 신청금액 합계', <Num value={pageAmount} />],
            ['승인 대기(마감)', <Num value={closedCount} />],
          ]}
        />
      </section>

      <section className='box span-8'>
        <h2>본예산 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='회계단위'>
            <TextInput value={draft.accountingUnit} onChange={(v) => setDraftValue('accountingUnit', v)} />
          </Field>
          <Field label='기수(회계연도)'>
            <NumberInput value={draft.fiscalYear} onChange={(v) => setDraftValue('fiscalYear', v)} />
          </Field>
          <Field label='프로젝트 ID'>
            <LookupSelect table='project' role={role} value={draft.projectId} onChange={(v) => setDraftValue('projectId', v)} />
          </Field>
          <Field label='예산그룹'>
            <TextInput value={draft.budgetGroup} onChange={(v) => setDraftValue('budgetGroup', v)} />
          </Field>
          <Field label='상태'>
            <Select value={draft.status} onChange={(v) => setDraftValue('status', v)} options={STATUS_OPTIONS} />
          </Field>
        </Filters>
        {list.error ? <ErrorText text={list.error} /> : null}
        <Band total={total} />
        <DataTable columns={columns} rows={rows} empty='조회된 본예산이 없습니다.' />
        <Pager page={page} size={20} total={total} onPage={setPage} />
      </section>

      <section className='box span-4'>
        <h2>처리 대기</h2>
        {waiting.error ? <ErrorText text={waiting.error} /> : null}
        <DataTable
          columns={[
            { key: 'accountingUnit', label: '회계단위' },
            { key: 'requestAmount', label: '신청금액', render: (r) => <Num value={r.requestAmount} /> },
            { key: 'status', label: '상태', render: (r) => <Badge value={r.status} /> },
          ]}
          rows={waiting.data ? waiting.data.items : []}
          onRowClick={(r) => openAction(r, ACTIONS['마감'][0])}
          empty='마감 상태의 본예산이 없습니다.'
        />
      </section>

      {target && action ? (
        <Drawer title={'본예산 ' + action[1]} onClose={closeDrawer}>
          <Pairs
            items={[
              ['본예산 ID', String(target.mainBudgetId)],
              ['회계단위', String(target.accountingUnit)],
              ['기수(회계연도)', String(target.fiscalYear)],
              ['프로젝트', <RefName table='project' role={role} value={target.projectId} />],
              ['예산과목', <RefName table='budget_item' role={role} value={target.budgetItemId} />],
              ['신청금액', <Num value={target.requestAmount} />],
              ['상태', <Badge value={target.status} />],
            ]}
          />
          <Form onSubmit={run} submit={action[1]} danger={action[0].indexOf('cancel') === 0}>
            <Field label='처리' wide>
              <span>{'이 본예산을 ' + action[1] + ' 처리합니다.'}</span>
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
